css:
.letter-page { font-family: Arial, sans-serif; color: #111; font-size: 11pt; line-height: 1.62; position: relative; }
.preview-banner { text-align:center; border:1px dashed #999; padding:6px 10px; margin-bottom:12px; color:#666; font-weight:700; letter-spacing:.5px; }
.expired-banner { text-align:center; border:1px solid #b00; padding:7px 10px; margin-bottom:14px; color:#900; font-weight:700; }
.expired-watermark { position:fixed; top:38%; left:16%; width:68%; text-align:center; transform:rotate(-28deg); font-size:54pt; line-height:1.05; color:#d2d2d2; opacity:.58; font-weight:700; z-index:0; }
.expired-watermark span { font-size:34pt; }
.letter-table, .section-table { width:100%; border-collapse:collapse; table-layout:fixed; }
.letter-table td, .section-table td { width:50%; vertical-align:top; }
.letter-left { direction:ltr; text-align:left; padding-right:13px; }
.letter-right { direction:rtl; text-align:right; padding-left:13px; font-family:Tahoma, Arial, sans-serif; }
.bilingual-divider { border-right:1px solid #ddd; }
.letter-subject { text-align:center; font-weight:700; font-size:13pt; margin:7px 0 16px; }
.letter-body { white-space:normal; }
.section-wrap { margin:0 0 14px; }
.section-title { font-weight:700; margin:0 0 6px; font-size:11.5pt; }
.section-page-break { page-break-before:always; }
.section-keep { page-break-inside:avoid; }
.letter-separator { border-top:1px solid #ddd; margin:20px 0; }
.signatory-block { margin-top:30px; page-break-inside:avoid; }
.signatory-assets { margin:8px 0; }
.signatory-assets img.signature { max-height:72px; max-width:190px; margin-right:16px; }
.signatory-assets img.stamp { max-height:90px; max-width:130px; }
.signatory-name { font-weight:700; }
.signatory-title { color:#444; }
.issue-meta { margin-top:26px; font-size:9pt; color:#666; }
.issue-meta span { margin-right:18px; }
.error-box { padding:16px; border:1px dashed #b00; color:#b00; }
@media print { .section-page-break { page-break-before:always; } .section-keep { page-break-inside:avoid; } }

.template-borderless-tables .letter-body table, .template-borderless-tables .letter-body thead, .template-borderless-tables .letter-body tbody, .template-borderless-tables .letter-body tr, .template-borderless-tables .letter-body th, .template-borderless-tables .letter-body td { border:0 !important; box-shadow:none !important; }\n.template-borderless-tables .letter-body th, .template-borderless-tables .letter-body td { background:transparent !important; }

html:
{% set preview = doc.get("_preview_mode") %}
{% if doc.docstatus != 1 and not preview %}
  <div class="error-box">{{ _("Cannot print a draft letter. Please issue the request first.") }}</div>
{% else %}
  <div class="letter-page {% if doc.table_print_style == 'Borderless Layout' %}template-borderless-tables{% endif %}">
    {% if doc.get("_expired_print") or doc.is_expired %}
      <div class="expired-watermark">EXPIRED<br><span>منتهي الصلاحية</span></div>
      <div class="expired-banner">{{ _("Historical copy - this letter is no longer valid for current use.") }} / نسخة تاريخية - هذا الخطاب غير ساري للاستخدام الحالي</div>
    {% endif %}
    {% if preview %}<div class="preview-banner">DRAFT / مسودة - PREVIEW ONLY / للمعاينة فقط</div>{% endif %}
    {% set mode = doc.language_mode or "Bilingual" %}
    {% set layout = doc.bilingual_layout or "Side by Side" %}
    {% set english_subject = doc.get("_print_rendered_subject_english") if doc.get("_print_rendered_subject_english") is not none else doc.rendered_subject_english %}
    {% set english_text = doc.get("_print_rendered_text_english") if doc.get("_print_rendered_text_english") is not none else doc.rendered_text_english %}
    {% set arabic_subject = doc.get("_print_rendered_subject_arabic") if doc.get("_print_rendered_subject_arabic") is not none else doc.rendered_subject_arabic %}
    {% set arabic_text = doc.get("_print_rendered_text_arabic") if doc.get("_print_rendered_text_arabic") is not none else doc.rendered_text_arabic %}
    {% set print_sections = doc.get("_print_rendered_sections") if doc.get("_print_rendered_sections") is not none else doc.rendered_sections %}

    {% macro english_single() %}
      <div class="letter-left">
        {% if english_subject %}<div class="letter-subject">{{ english_subject }}</div>{% endif %}
        <div class="letter-body">{{ (english_text or "") | safe }}</div>
      </div>
    {% endmacro %}

    {% macro arabic_single() %}
      <div class="letter-right">
        {% if arabic_subject %}<div class="letter-subject">{{ arabic_subject }}</div>{% endif %}
        <div class="letter-body">{{ (arabic_text or "") | safe }}</div>
      </div>
    {% endmacro %}

    {% if print_sections %}
      {% if english_subject or arabic_subject %}
        {% if mode == "Bilingual" and layout == "Side by Side" %}
          <table class="letter-table"><tr>
            <td class="letter-left bilingual-divider">{% if english_subject %}<div class="letter-subject">{{ english_subject }}</div>{% endif %}</td>
            <td class="letter-right">{% if arabic_subject %}<div class="letter-subject">{{ arabic_subject }}</div>{% endif %}</td>
          </tr></table>
        {% elif mode == "Arabic Only" %}
          <div class="letter-subject letter-right">{{ arabic_subject or "" }}</div>
        {% else %}
          <div class="letter-subject letter-left">{{ english_subject or "" }}</div>
        {% endif %}
      {% endif %}

      {% for section in print_sections %}
        <div class="section-wrap {% if section.page_break_before %}section-page-break{% endif %} {% if section.keep_together %}section-keep{% endif %}">
          {% if mode == "Arabic Only" %}
            <div class="letter-right">
              {% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}
              <div class="letter-body">{{ (section.content_arabic or "") | safe }}</div>
            </div>
          {% elif mode == "English Only" %}
            <div class="letter-left">
              {% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}
              <div class="letter-body">{{ (section.content_english or "") | safe }}</div>
            </div>
          {% elif layout == "Side by Side" %}
            <table class="section-table"><tr>
              <td class="letter-left bilingual-divider">
                {% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}
                <div class="letter-body">{{ (section.content_english or "") | safe }}</div>
              </td>
              <td class="letter-right">
                {% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}
                <div class="letter-body">{{ (section.content_arabic or "") | safe }}</div>
              </td>
            </tr></table>
          {% elif layout == "Arabic then English" %}
            <div class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></div>
            <div class="letter-separator"></div>
            <div class="letter-left">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></div>
          {% else %}
            <div class="letter-left">{% if section.section_title_english %}<div class="section-title">{{ section.section_title_english }}</div>{% endif %}<div class="letter-body">{{ (section.content_english or "") | safe }}</div></div>
            <div class="letter-separator"></div>
            <div class="letter-right">{% if section.section_title_arabic %}<div class="section-title">{{ section.section_title_arabic }}</div>{% endif %}<div class="letter-body">{{ (section.content_arabic or "") | safe }}</div></div>
          {% endif %}
        </div>
      {% endfor %}
    {% else %}
      {% if mode == "Arabic Only" %}
        {{ arabic_single() }}
      {% elif mode == "English Only" %}
        {{ english_single() }}
      {% elif layout == "Arabic then English" %}
        {{ arabic_single() }}<div class="letter-separator"></div>{{ english_single() }}
      {% elif layout == "English then Arabic" %}
        {{ english_single() }}<div class="letter-separator"></div>{{ arabic_single() }}
      {% else %}
        <table class="letter-table"><tr>
          <td class="bilingual-divider">{{ english_single() }}</td>
          <td>{{ arabic_single() }}</td>
        </tr></table>
      {% endif %}
    {% endif %}

    {% if doc.requires_signature or doc.requires_stamp %}
      <div class="signatory-block {% if mode == 'Arabic Only' %}letter-right{% else %}letter-left{% endif %}">
        <div class="signatory-assets">
          {% if doc.signature_image_data %}<img class="signature" src="{{ doc.signature_image_data }}">{% endif %}
          {% if doc.stamp_image_data %}<img class="stamp" src="{{ doc.stamp_image_data }}">{% endif %}
        </div>
        {% if mode == "Arabic Only" %}
          <div class="signatory-name">{{ doc.signatory_name_arabic or doc.signatory_name_english or "" }}</div>
          <div class="signatory-title">{{ doc.signatory_title_arabic or doc.signatory_title_english or "" }}</div>
        {% elif mode == "English Only" %}
          <div class="signatory-name">{{ doc.signatory_name_english or "" }}</div>
          <div class="signatory-title">{{ doc.signatory_title_english or "" }}</div>
        {% else %}
          <div class="signatory-name">{{ doc.signatory_name_english or "" }}{% if doc.signatory_name_arabic %} / {{ doc.signatory_name_arabic }}{% endif %}</div>
          <div class="signatory-title">{{ doc.signatory_title_english or "" }}{% if doc.signatory_title_arabic %} / {{ doc.signatory_title_arabic }}{% endif %}</div>
        {% endif %}
      </div>
    {% endif %}

    <div class="issue-meta">
      {% if doc.issue_date %}<span>{{ _("Issue Date") }}: {{ doc.issue_date }}</span>{% endif %}
      {% if doc.valid_until %}<span>{{ _("Valid Until") }}: {{ doc.valid_until }}</span>{% endif %}
      <span>{{ _("Reference") }}: {{ doc.name }}</span>
    </div>
  </div>
{% endif %}
